CREATE TABLE IF NOT EXISTS orders (
  id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, customer_name VARCHAR(150) NOT NULL, customer_email VARCHAR(255), product VARCHAR(150) NOT NULL, amount DECIMAL(12,2) NOT NULL, status ENUM('Unpaid','Pending','Paid') NOT NULL DEFAULT 'Unpaid', due_date DATE NOT NULL, paid_at DATETIME NULL, last_reminder_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS payment_audit_logs (id INT AUTO_INCREMENT PRIMARY KEY, order_id INT NOT NULL, user_id INT NOT NULL, previous_status VARCHAR(20) NOT NULL, new_status VARCHAR(20) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS payment_receipts (id INT AUTO_INCREMENT PRIMARY KEY, order_id INT NOT NULL, receipt_number VARCHAR(80) UNIQUE NOT NULL, file_path VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE);
